<?php
declare(strict_types=1);

namespace KhoNpl\Services;

use KhoNpl\Core\Database;
use KhoNpl\Core\HttpException;

final class ReversalService
{
    public function __construct(private readonly \PDO $db, private readonly AuthService $auth, private readonly InventoryService $inventory) {}

    public function preview(string $email, string $code): array
    {
        $this->auth->require($email, ['PRODUCTION_MANAGER']);
        $doc=$this->findDocument($code); $lines=[];
        foreach($doc['lines'] as $l){$x=$this->movementFor($doc,$l);if($x['qty']<=0)continue;$b=$this->inventory->balance((string)$l['material_id']);$lines[]=['materialId'=>$l['material_id'],'materialName'=>$l['material_name_snapshot']??$l['material_id'],'qty'=>$x['qty'],'unitCost'=>$x['cost'],'direction'=>$x['direction'],'stockBefore'=>$b['qty'],'stockAfter'=>$x['direction']==='IN'?$b['qty']+$x['qty']:$b['qty']-$x['qty']];}
        return ['documentCode'=>$doc['code'],'documentType'=>$doc['type'],'status'=>$doc['status'],'canReverse'=>$doc['status']==='POSTED','lines'=>$lines];
    }

    public function reverse(string $email, array $p): array
    {
        $this->auth->require($email, ['PRODUCTION_MANAGER']); $code=code($p['documentCode']??'');$reason=s($p['reason']??'');$client=s($p['clientRequestId']??'')?:uuid_id('REQ');require_true($code&&$reason,'Phải nhập mã chứng từ và lý do đảo');
        return Database::transaction(function()use($email,$code,$reason,$client,$p){
            $old=$this->db->prepare('SELECT response_json,status FROM idempotency_requests WHERE client_request_id=? FOR UPDATE');$old->execute([$client]);$prior=$old->fetch();if($prior&&$prior['status']==='DONE')return json_decode((string)$prior['response_json'],true)?:[];
            if(!$prior)$this->db->prepare('INSERT INTO idempotency_requests(client_request_id,operation,user_email,request_hash,status) VALUES(?,?,?,?,"PROCESSING")')->execute([$client,'REVERSAL_POST',$email,json_hash($p)]);
            $doc=$this->findDocument($code);require_true($doc['status']==='POSTED','Chứng từ không ở trạng thái POSTED nên không thể đảo','DOCUMENT_NOT_POSTED',409);
            $items=[];foreach($doc['lines'] as $l){$x=$this->movementFor($doc,$l);if($x['qty']<=0)continue;if($doc['type']==='ISSUE'){$q=$this->db->prepare('SELECT COUNT(*) FROM production_returns WHERE source_issue_line_id=? AND status="POSTED"');$q->execute([$l['issue_line_id']]);require_true((int)$q->fetchColumn()===0,'Phiếu xuất đã có phiếu trả NPL; hãy đảo phiếu trả trước','BLOCK_REVERSAL_ISSUE',409);}if($doc['type']==='ADJUSTMENT'&&in_array($l['adjustment_type'],['IN','REVERSAL_IN'],true)){$q=$this->db->prepare('SELECT COUNT(*) FROM stock_ledger WHERE material_id=? AND posted_at>(SELECT posted_at FROM stock_ledger WHERE transaction_line_id=? LIMIT 1) AND transaction_id<>?');$q->execute([$l['material_id'],$l['adjustment_id'],$l['adjustment_id']]);require_true((int)$q->fetchColumn()===0,'Vật tư đã có giao dịch sau điều chỉnh tăng; hãy dùng điều chỉnh hiện tại','BLOCK_REVERSAL_ADJUSTMENT',409);} $items[]=['line'=>$l]+$x;}
            $date=date_ymd($p['reversalDate']??null);$seq=$this->nextCode('REVERSAL',$date);$out=[];$i=0;
            foreach($items as $item){$i++;$l=$item['line'];$id=uuid_id('RV');$adjCode=$seq.'-'.str_pad((string)$i,2,'0',STR_PAD_LEFT);$mv=$this->inventory->movement(['ledger_id'=>'LG-'.$id,'transaction_date'=>$date,'transaction_type'=>'DAO_'.$doc['type'],'transaction_id'=>$id,'transaction_line_id'=>$id,'document_code'=>$adjCode,'material_id'=>$l['material_id'],'qty_in'=>$item['direction']==='IN'?$item['qty']:0,'qty_out'=>$item['direction']==='OUT'?$item['qty']:0,'unit_cost'=>$item['cost'],'order_code'=>$l['order_code']??$doc['header']['order_code']??'','execution_code'=>$l['execution_code']??$doc['header']['execution_code']??'','product_code'=>$l['product_code']??'','supplier_id'=>$doc['header']['supplier_id']??'','pr_code'=>$l['pr_code']??'','created_by'=>$email,'client_request_id'=>$client]);$this->db->prepare('INSERT INTO adjustments(adjustment_id,adjustment_code,adjustment_date,material_id,adjustment_type,qty,unit_cost,amount,reason_code,reason_detail,reference_transaction_id,requested_by,approved_by,status,posted_by,posted_at,note,client_request_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$adjCode,$date,$l['material_id'],$item['direction']==='IN'?'REVERSAL_IN':'REVERSAL_OUT',$item['qty'],$item['cost'],$item['qty']*$item['cost'],'DATA_ERROR',$reason,$item['sourceLine'],$email,$email,'POSTED',$email,date('Y-m-d H:i:s'),'Đảo '.$code,$client.'-'.$i]);$out[]=['adjustmentId'=>$id,'adjustmentCode'=>$adjCode,'materialId'=>$l['material_id'],'qty'=>$item['qty'],'direction'=>$item['direction'],'stockAfter'=>$mv['qty']];}
            if($doc['type']==='RECEIPT'){$this->db->prepare('UPDATE receipts SET status="REVERSED" WHERE receipt_id=?')->execute([$doc['id']]);foreach($doc['lines'] as $l){$q=$this->db->prepare('UPDATE purchase_request_lines SET received_qty=GREATEST(received_qty-?,0),remaining_qty=remaining_qty+?,line_status="PARTIAL" WHERE pr_ref_key=?');$q->execute([n($l['accepted_qty']),n($l['accepted_qty']),$l['pr_ref_key']]);}}elseif($doc['type']==='ISSUE'){$this->db->prepare('UPDATE issues SET status="REVERSED",post_engine_status="DA_DAO" WHERE issue_id=?')->execute([$doc['id']]);$this->db->prepare('UPDATE issue_lines SET issue_status_ref="REVERSED" WHERE issue_id=?')->execute([$doc['id']]);$reservationIds=[];foreach($doc['lines'] as $l)$reservationIds[$l['reservation_id']]=true;foreach(array_keys($reservationIds) as $reservationId)$this->recalculateIssueReservation($reservationId);}elseif($doc['type']==='RETURN')$this->db->prepare('UPDATE production_returns SET status="REVERSED" WHERE return_id=?')->execute([$doc['id']]);else $this->db->prepare('UPDATE adjustments SET status="REVERSED" WHERE adjustment_code=? AND status="POSTED"')->execute([$code]);
            $this->db->prepare('INSERT INTO audit_logs(user_email,action,object_type,object_id,reason,client_request_id,environment) VALUES(?,?,?,?,?,?,?)')->execute([$email,'REVERSE_'.$doc['type'],$doc['type'],$doc['id'],$reason,$client,getenv('KHO_ENV')?:'THU_NGHIEM']);$response=['reversalCode'=>$seq,'documentCode'=>$code,'documentType'=>$doc['type'],'lineCount'=>count($out),'lines'=>$out,'clientRequestId'=>$client];$this->db->prepare('UPDATE idempotency_requests SET status="DONE",response_json=?,completed_at=NOW() WHERE client_request_id=?')->execute([json_encode($response,JSON_UNESCAPED_UNICODE),$client]);return $response;
        });
    }

    private function movementFor(array $doc,array $l): array
    { if($doc['type']==='RECEIPT')return['qty'=>n($l['accepted_qty']),'cost'=>n($l['actual_unit_price']),'direction'=>'OUT','sourceLine'=>$l['receipt_line_id']];if($doc['type']==='ISSUE')return['qty'=>n($l['issue_qty']),'cost'=>n($l['management_unit_cost']),'direction'=>'IN','sourceLine'=>$l['issue_line_id']];if($doc['type']==='RETURN')return['qty'=>n($l['usable_stock_qty']),'cost'=>n($l['unit_cost']),'direction'=>'OUT','sourceLine'=>$l['return_id']];$in=in_array($l['adjustment_type'],['IN','REVERSAL_IN'],true);return['qty'=>n($l['qty']),'cost'=>n($l['unit_cost']),'direction'=>$in?'OUT':'IN','sourceLine'=>$l['adjustment_id']]; }
    private function recalculateIssueReservation(string $reservationId): void
    { $q=$this->db->prepare('SELECT confirmed_reserved_qty,released_qty FROM reservations WHERE reservation_id=? FOR UPDATE');$q->execute([$reservationId]);$reservation=$q->fetch();if(!$reservation)return;$q=$this->db->prepare('SELECT COALESCE(SUM(issue_qty),0) FROM issue_lines WHERE reservation_id=? AND issue_status_ref="POSTED"');$q->execute([$reservationId]);$issued=n($q->fetchColumn());$remaining=max(n($reservation['confirmed_reserved_qty'])-$issued-n($reservation['released_qty']),0);$status=$remaining<=1e-9?'CLOSED':($issued>1e-9?'PARTIAL_ISSUED':'CONFIRMED');$this->db->prepare('UPDATE reservations SET issued_qty=?,remaining_reserved_qty=?,status=?,updated_at=NOW() WHERE reservation_id=?')->execute([$issued,$remaining,$status,$reservationId]); }
    private function nextCode(string $type,string $date): string
    { $this->db->prepare('INSERT INTO document_sequences(doc_type,doc_date,last_no) VALUES(?,?,1) ON DUPLICATE KEY UPDATE last_no=last_no+1')->execute([$type,$date]);$q=$this->db->prepare('SELECT last_no FROM document_sequences WHERE doc_type=? AND doc_date=? FOR UPDATE');$q->execute([$type,$date]);return 'RV'.date('ymd',strtotime($date)).'-'.str_pad((string)$q->fetchColumn(),3,'0',STR_PAD_LEFT); }
    private function findDocument(string $code): array
    { $code=code($code);$q=$this->db->prepare('SELECT * FROM receipts WHERE receipt_code=?');$q->execute([$code]);if($h=$q->fetch()){$x=$this->db->prepare('SELECT * FROM receipt_lines WHERE receipt_id=?');$x->execute([$h['receipt_id']]);return['type'=>'RECEIPT','id'=>$h['receipt_id'],'code'=>$code,'status'=>$h['status'],'header'=>$h,'lines'=>$x->fetchAll()];}$q=$this->db->prepare('SELECT * FROM issues WHERE issue_code=?');$q->execute([$code]);if($h=$q->fetch()){$x=$this->db->prepare('SELECT * FROM issue_lines WHERE issue_id=?');$x->execute([$h['issue_id']]);return['type'=>'ISSUE','id'=>$h['issue_id'],'code'=>$code,'status'=>$h['status'],'header'=>$h,'lines'=>$x->fetchAll()];}$q=$this->db->prepare('SELECT * FROM production_returns WHERE return_code=?');$q->execute([$code]);if($h=$q->fetch())return['type'=>'RETURN','id'=>$h['return_id'],'code'=>$code,'status'=>$h['status'],'header'=>$h,'lines'=>[$h]];$q=$this->db->prepare('SELECT * FROM adjustments WHERE adjustment_code=?');$q->execute([$code]);$rows=$q->fetchAll();if($rows)return['type'=>'ADJUSTMENT','id'=>$code,'code'=>$code,'status'=>$rows[0]['status'],'header'=>$rows[0],'lines'=>$rows];throw new HttpException('Không tìm thấy chứng từ: '.$code,'DOCUMENT_NOT_FOUND',404); }
}
